# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _simple_chart(data=None, mark="point", x="x", y="y"):
    """Build a minimal Chart for testing."""
    if data is None:
        data = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    return Chart(data).mark_point().encode(x=x, y=y) if mark == "point" else Chart(data).mark_line().encode(x=x, y=y)


def _assert_valid_svg(svg: str) -> None:
    """Assert the SVG string is structurally valid (not NaN/Infinity-poisoned)."""
    assert isinstance(svg, str), f"Expected str, got {type(svg).__name__}"
    assert svg.startswith("<svg") or svg.startswith("<?xml"), f"Bad SVG start: {svg[:80]!r}"
    assert "NaN" not in svg, "SVG contains 'NaN'"
    assert "Infinity" not in svg, "SVG contains 'Infinity'"


# ---------------------------------------------------------------------------
# 1. configure() propagation through composition operators
# ---------------------------------------------------------------------------


def test_configure_preserved_through_layer_add():
    """Chart + Chart should merge _configure lists from both sides.

    Targets __add__ lines 4134-4135 in chart.py: rhs._configure merge.
    """
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").configure(
        axis=AxisConfig(label_angle=-45)
    )
    c2 = Chart(df).mark_line().encode(x="x", y="y").configure(
        grid=GridConfig(color="#eee")
    )
    layered = c1 + c2
    # Both configure layers should be present
    assert len(layered._configure) == 2
    # Render should succeed without error
    svg = layered.show_svg()
    _assert_valid_svg(svg)


def test_configure_on_hconcat_fans_out_to_sub_charts():
    """Calling .configure() on a Chart before | preserves it when rendering.

    Targets _render_inputs -> _resolve_chart_config in _render.py line 282.
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").configure(
        axis=AxisConfig(label_angle=-30)
    )
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    svg = combined.show_svg()
    _assert_valid_svg(svg)
    # The composed SVG should include both sub-charts
    assert svg.count('transform="translate(') >= 2


def test_configure_on_vconcat_fans_out():
    """Calling .configure() on a Chart before & preserves it when rendering."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").configure(
        legend=LegendConfig(orient="bottom")
    )
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 & c2
    svg = combined.show_svg()
    _assert_valid_svg(svg)


def test_configure_stacking_multiple_layers():
    """Multiple .configure() calls on same chart should accumulate, not replace.

    Targets chart.py configure() line 4705: new._configure = new._configure + [cfg].
    """
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c = (
        Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure(axis=AxisConfig(label_angle=-30))
        .configure(grid=GridConfig(color="#ddd"))
        .configure(padding=PaddingConfig(top=20))
    )
    assert len(c._configure) == 3
    svg = c.show_svg()
    _assert_valid_svg(svg)


def test_configure_override_conflict_in_merge():
    """When both sides of + have axis config, later one wins per key.

    Targets _resolve_chart_config in _render.py lines 284-288: dict merge.
    """
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").configure(
        axis=AxisConfig(label_angle=-45, tick_count=5)
    )
    c2 = Chart(df).mark_line().encode(x="x", y="y").configure(
        axis=AxisConfig(label_angle=0)  # should override -45 in merge
    )
    layered = c1 + c2
    merged = layered._resolve_chart_config()
    # The axis dict should exist and contain the merged result
    assert "axis" in merged
    # RHS should win for label_angle but LHS tick_count should survive
    assert merged["axis"]["label_angle"] == 0
    assert merged["axis"]["tick_count"] == 5


