def test_hconcat_nested_in_vconcat():
    """Nesting (c1 | c2) & c3 produces VConcat containing HConcat.

    Targets composition operator precedence: & has higher precedence than |
    at Python level but the explicit parens override.
    """
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    c3 = Chart(df).mark_line().encode(x="x", y="y")
    result = (c1 | c2) & c3
    assert isinstance(result, VConcatChart)
    assert isinstance(result.charts[0], HConcatChart)
    svg = result.show_svg()
    _assert_valid_svg(svg)


def test_deeply_nested_composition():
    """Three levels of nesting: ((c1 | c2) & c3) | c4."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    c3 = Chart(df).mark_line().encode(x="x", y="y")
    c4 = Chart(df).mark_point().encode(x="x", y="y")
    result = ((c1 | c2) & c3) | c4
    assert isinstance(result, HConcatChart)
    svg = result.show_svg()
    _assert_valid_svg(svg)


