def test_layer_warns_on_coord_conflict():
    """Layering charts with different coord systems should warn.

    Targets composition._warn_on_layer_conflicts lines 2032-2046.
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").coord(fr.CoordFlip())
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        _ = c1 + c2
        coord_warns = [x for x in w if "coord" in str(x.message).lower() or "facet" in str(x.message).lower()]
        assert len(coord_warns) >= 1, "Expected warning about conflicting coord/facet"


def test_layer_warns_on_facet_conflict():
    """Layering charts with different facets should warn.

    Targets composition._warn_on_layer_conflicts.
    """
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0], "g": ["a", "b"]})
    c1 = Chart(df).mark_point().encode(x="x", y="y").facet(col="g")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        _ = c1 + c2
        warns = [x for x in w if "coord" in str(x.message).lower() or "facet" in str(x.message).lower()]
        assert len(warns) >= 1, "Expected warning about conflicting facet"


