def test_facet_with_many_panels():
    """Facet with 10+ panels should render without overflow/NaN.

    Targets the Rust facet layout code with many panels.
    """
    import pyarrow as pa

    groups = [f"G{i}" for i in range(12)] * 3  # 12 groups, 3 rows each
    tbl = pa.table(
        {
            "x": pa.array(list(range(36)), type=pa.int64()),
            "y": pa.array(list(range(36)), type=pa.int64()),
            "grp": pa.array(groups, type=pa.string()),
        }
    )
    df = pl.from_arrow(tbl)
    chart = Chart(df).mark_point().encode(x="x", y="y").facet(col="grp", ncols=4)
    spec = chart.to_spec()
    from ferrum._core import render_svg

    svg = render_svg(spec, tbl, viewport=(1200.0, 800.0), theme={})
    _assert_valid_svg(svg)


