def test_theme_propagates_through_hconcat():
    """Calling .theme() on HConcatChart should propagate to all sub-charts.

    Targets _ChartLike.theme -> _rebuild_with_charts (composition.py line 219).
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    # Apply theme to the composition
    dark = fr.themes.dark
    themed = combined.theme(dark)
    assert isinstance(themed, HConcatChart)
    for c in themed.charts:
        assert c._theme is dark


def test_properties_propagates_through_vconcat():
    """Calling .properties() on VConcatChart should propagate to all sub-charts.

    Targets _ChartLike.properties -> _rebuild_with_charts (composition.py line 236).
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 & c2
    updated = combined.properties(width=800, height=600)
    assert isinstance(updated, VConcatChart)
    for c in updated.charts:
        assert c._width == 800
        assert c._height == 600


def test_theme_on_layer_chart_propagates():
    """Calling .theme() on LayerChart should propagate to all member charts."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    lc = LayerChart(c1, c2)
    dark = fr.themes.dark
    themed = lc.theme(dark)
    assert isinstance(themed, LayerChart)
    for c in themed.charts:
        assert c._theme is dark


