    c = (
        Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure(
            axis=AxisConfig(label_angle=-30),
            legend=LegendConfig(orient="bottom"),
            title=TitleConfig(font_size=16),
            grid=GridConfig(color="#ddd"),
            padding=PaddingConfig(top=20),
            color=ColorConfig(scheme="tableau10"),
        )
    )
    merged = c._resolve_chart_config()
    assert "axis" in merged
    assert "legend" in merged
    assert "title" in merged
    assert "grid" in merged
    assert "padding" in merged
    assert "color" in merged
    assert merged["axis"]["label_angle"] == -30
    assert merged["legend"]["orient"] == "bottom"


